enum class thresholdEventOffsets : uint8_t {
  lowerNonCritGoingLow = 0x00,
  lowerCritGoingLow = 0x02,
  upperNonCritGoingHigh = 0x07,
  upperCritGoingHigh = 0x09,
};

static constexpr const uint8_t thresholdEventDataTriggerReadingByte2 = (1 << 6);
static constexpr const uint8_t thresholdEventDataTriggerReadingByte3 = (1 << 4);

static const std::string openBMCMessageRegistryVersion("0.1");
static const std::string dmtfMessageRegistryVersion("1.0");

#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
bool isOutsideNormalRange(std::shared_ptr<sdbusplus::asio::connection> conn,
                          std::string sender, std::string path) {
  // Check if either warning alarm high or low is asserted
  sdbusplus::message_t getwarningAsserted =
      conn->new_method_call(sender.c_str(), path.c_str(),
                            "org.freedesktop.DBus.Properties", "GetAll");
  getwarningAsserted.append("xyz.openbmc_project.Sensor.Threshold.Warning");
  boost::container::flat_map<std::string, std::variant<bool>> warningAsserted;
  try {
    sdbusplus::message_t getwarningAssertedResp =
        conn->call(getwarningAsserted);
    getwarningAssertedResp.read(warningAsserted);
  } catch (const sdbusplus::exception_t &) {
    std::cerr << "error getting warning asserted from " << path << "\n";
    return false;
  }
  bool warningAssertedHigh = false;
  auto findWarningAssertedHigh = warningAsserted.find("WarningAlarmHigh");
  if (findWarningAssertedHigh != warningAsserted.end()) {
    warningAssertedHigh = std::get<bool>(findWarningAssertedHigh->second);
  }
  bool warningAssertedLow = false;
  auto findWarningAssertedLow = warningAsserted.find("WarningAlarmLow");
  if (findWarningAssertedLow != warningAsserted.end()) {
    warningAssertedLow = std::get<bool>(findWarningAssertedLow->second);
  }
  return warningAssertedHigh || warningAssertedLow;
}
#endif

inline static sdbusplus::bus::match_t
startThresholdAssertMonitor(std::shared_ptr<sdbusplus::asio::connection> conn) {
  auto thresholdAssertMatcherCallback = [conn](sdbusplus::message_t &msg) {
    // This static set of std::pair<path, event> tracks asserted events to
    // avoid duplicate logs or deasserts logged without an assert
    static boost::container::flat_set<std::pair<std::string, std::string>>
        assertedEvents;
    std::vector<uint8_t> eventData(selEvtDataMaxSize, selEvtDataUnspecified);

    // Get the event type and assertion details from the message
    std::string sensorName;
    std::string thresholdInterface;
    std::string event;
    bool assert;
    double assertValue;
    try {
      msg.read(sensorName, thresholdInterface, event, assert, assertValue);
    } catch (const sdbusplus::exception_t &) {
      std::cerr << "error getting assert signal data from " << msg.get_path()
                << "\n";
      return;
    }

    // Check the asserted events to determine if we should log this event
    std::pair<std::string, std::string> pathAndEvent(
        std::string(msg.get_path()), event);
    if (assert) {
      // For asserts, add the event to the set and only log it if it's new
      if (assertedEvents.insert(pathAndEvent).second == false) {
        // event is already in the set
        return;
      }
    } else {
      // For deasserts, remove the event and only log the deassert if it
      // was asserted
      if (assertedEvents.erase(pathAndEvent) == 0) {
        // asserted event was not in the set
        return;
      }
    }

    // Set the IPMI threshold event type based on the event details from the
    // message
    if (event == "CriticalAlarmLow") {
      eventData[0] =
          static_cast<uint8_t>(thresholdEventOffsets::lowerCritGoingLow);
    } else if (event == "WarningAlarmLow") {
      eventData[0] =
          static_cast<uint8_t>(thresholdEventOffsets::lowerNonCritGoingLow);
    } else if (event == "WarningAlarmHigh") {
      eventData[0] =
          static_cast<uint8_t>(thresholdEventOffsets::upperNonCritGoingHigh);
    } else if (event == "CriticalAlarmHigh") {
      eventData[0] =
          static_cast<uint8_t>(thresholdEventOffsets::upperCritGoingHigh);
    }
    // Indicate that bytes 2 and 3 are threshold sensor trigger values
    eventData[0] |= thresholdEventDataTriggerReadingByte2 |
                    thresholdEventDataTriggerReadingByte3;

    // Get the sensor reading to put in the event data
    sdbusplus::message_t getSensorValue =
        conn->new_method_call(msg.get_sender(), msg.get_path(),
                              "org.freedesktop.DBus.Properties", "GetAll");
    getSensorValue.append("xyz.openbmc_project.Sensor.Value");
    boost::container::flat_map<std::string, std::variant<double, int64_t>>
        sensorValue;
    try {
      sdbusplus::message_t getSensorValueResp = conn->call(getSensorValue);
      getSensorValueResp.read(sensorValue);
    } catch (const sdbusplus::exception_t &) {
      std::cerr << "error getting sensor value from " << msg.get_path() << "\n";
      return;
    }
    double max = 0;
    auto findMax = sensorValue.find("MaxValue");
    if (findMax != sensorValue.end()) {
      max = std::visit(ipmi::VariantToDoubleVisitor(), findMax->second);
    }
    double min = 0;
    auto findMin = sensorValue.find("MinValue");
    if (findMin != sensorValue.end()) {
      min = std::visit(ipmi::VariantToDoubleVisitor(), findMin->second);
    }

    try {
      eventData[1] = ipmi::getScaledIPMIValue(assertValue, max, min);
    } catch (const std::exception &e) {
      std::cerr << e.what();
      eventData[1] = selEvtDataUnspecified;
    }

    // Get the threshold value to put in the event data
    // Get the threshold parameter by removing the "Alarm" text from the
    // event string
    std::string alarm("Alarm");
    if (std::string::size_type pos = event.find(alarm);
        pos != std::string::npos) {
      event.erase(pos, alarm.length());
    }
    sdbusplus::message_t getThreshold =
        conn->new_method_call(msg.get_sender(), msg.get_path(),
                              "org.freedesktop.DBus.Properties", "Get");
    getThreshold.append(thresholdInterface, event);
    std::variant<double, int64_t> thresholdValue;
    try {
      sdbusplus::message_t getThresholdResp = conn->call(getThreshold);
      getThresholdResp.read(thresholdValue);
    } catch (const sdbusplus::exception_t &) {
      std::cerr << "error getting sensor threshold from " << msg.get_path()
                << "\n";
      return;
    }
    double thresholdVal =
        std::visit(ipmi::VariantToDoubleVisitor(), thresholdValue);

    double scale = 0;
    auto findScale = sensorValue.find("Scale");
    if (findScale != sensorValue.end()) {
      scale = std::visit(ipmi::VariantToDoubleVisitor(), findScale->second);
      thresholdVal *= std::pow(10, scale);
    }
    try {
      eventData[2] = ipmi::getScaledIPMIValue(thresholdVal, max, min);
    } catch (const std::exception &e) {
      std::cerr << e.what();
      eventData[2] = selEvtDataUnspecified;
    }

    std::string threshold;
    std::string direction;
#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
    std::string redfishMessageID = "SensorEvent." + dmtfMessageRegistryVersion;
#else
    std::string redfishMessageID = "OpenBMC." + openBMCMessageRegistryVersion;
#endif
    enum EventType { eventNone, eventInfo, eventWarn, eventErr };
    [[maybe_unused]] EventType eventType = eventNone;
    if (event == "CriticalLow") {
      threshold = "critical low";
      if (assert) {
        eventType = eventErr;
        direction = "low";
#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
        redfishMessageID += ".ReadingBelowLowerCriticalThreshold";
#else
        redfishMessageID += ".SensorThresholdCriticalLowGoingLow";
#endif
      } else {
        eventType = eventInfo;
        direction = "high";
#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
        if (isOutsideNormalRange(conn, msg.get_sender(), msg.get_path())) {
          redfishMessageID += ".ReadingAboveLowerCriticalThreshold";
        } else {
          redfishMessageID += ".SensorReadingNormalRange";
        }
#else
        redfishMessageID += ".SensorThresholdCriticalLowGoingHigh";
#endif
      }
    } else if (event == "WarningLow") {
      threshold = "warning low";
      if (assert) {
        eventType = eventWarn;
        direction = "low";
#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
        redfishMessageID += ".ReadingBelowLowerCautionThreshold";
#else
        redfishMessageID += ".SensorThresholdWarningLowGoingLow";
#endif
      } else {
        eventType = eventInfo;
        direction = "high";
#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
        redfishMessageID += ".SensorReadingNormalRange";
#else
        redfishMessageID += ".SensorThresholdWarningLowGoingHigh";
#endif
      }
    } else if (event == "WarningHigh") {
      threshold = "warning high";
      if (assert) {
        eventType = eventWarn;
        direction = "high";
#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
        redfishMessageID += ".ReadingAboveUpperCautionThreshold";
#else
        redfishMessageID += ".SensorThresholdWarningHighGoingHigh";
#endif
      } else {
        eventType = eventInfo;
        direction = "low";
#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
        redfishMessageID += ".SensorReadingNormalRange";
#else
        redfishMessageID += ".SensorThresholdWarningHighGoingLow";
#endif
      }
    } else if (event == "CriticalHigh") {
      threshold = "critical high";
      if (assert) {
        eventType = eventErr;
        direction = "high";
#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
        redfishMessageID += ".ReadingAboveUpperCriticalThreshold";
#else
        redfishMessageID += ".SensorThresholdCriticalHighGoingHigh";
#endif
      } else {
        eventType = eventInfo;
        direction = "low";
#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
        if (isOutsideNormalRange(conn, msg.get_sender(), msg.get_path())) {
          redfishMessageID += ".ReadingBelowUpperCriticalThreshold";
        } else {
          redfishMessageID += ".SensorReadingNormalRange";
        }
#else
        redfishMessageID += ".SensorThresholdCriticalHighGoingLow";
#endif
      }
    }
#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
    else if (event == "HardShutdownLow") {
      threshold = "hard shutdown low";
      if (assert) {
        eventType = eventErr;
        direction = "low";
        redfishMessageID += ".ReadingBelowLowerFatalThreshold";
      } else {
        eventType = eventInfo;
        direction = "high";
        if (isOutsideNormalRange(conn, msg.get_sender(), msg.get_path())) {
          redfishMessageID += ".ReadingAboveLowerFatalThreshold";
        } else {
          redfishMessageID += ".SensorReadingNormalRange";
        }
      }
    } else if (event == "HardShutdownHigh") {
      threshold = "hard shutdown high";
      if (assert) {
        eventType = eventErr;
        direction = "high";
        redfishMessageID += ".ReadingAboveUpperFatalThreshold";
      } else {
        eventType = eventInfo;
        direction = "low";
        if (isOutsideNormalRange(conn, msg.get_sender(), msg.get_path())) {
          redfishMessageID += ".ReadingBelowUpperFatalThreshold";
        } else {
          redfishMessageID += ".SensorReadingNormalRange";
        }
      }
    } else {
      // Other threshold types, such as SoftShutdown, are not supported
      return;
    }
#endif
    // Downstream code
    // std::string journalMsg(std::string(sensorName) + " sensor crossed a "
    // +
    //                            threshold + " threshold going " +
    //                            direction +
    //                            ". Reading=" + std::to_string(assertValue)
    //                            + " Threshold=" +
    //                            std::to_string(thresholdVal) +
    //                            ".");

    std::string journalMsg(std::string(sensorName) + " " + threshold +
                           " threshold " + (assert ? "assert" : "deassert") +
                           ". Reading=" + std::to_string(assertValue) +
                           " Threshold=" + std::to_string(thresholdVal) + ".");

#ifdef SEL_LOGGER_SEND_TO_LOGGING_SERVICE
    std::string LogLevel = "";
    switch (eventType) {
    case eventInfo: {
      LogLevel = "xyz.openbmc_project.Logging.Entry.Level.Informational";
      break;
    }
    case eventWarn: {
      LogLevel = "xyz.openbmc_project.Logging.Entry.Level.Warning";
      break;
    }
    case eventErr: {
      LogLevel = "xyz.openbmc_project.Logging.Entry.Level.Critical";
      break;
    }
    default: {
      LogLevel = "xyz.openbmc_project.Logging.Entry.Level.Debug";
      break;
    }
    }

#ifdef SEL_LOGGER_USE_DMTF_REGISTRY
    // Get the sensor unit via a dbus call and process it to remove the
    // "xyz.openbmc_project.Sensor.Value.Unit." prefix
    std::string unit = "";
    sdbusplus::message_t getSensorUnit =
        conn->new_method_call(msg.get_sender(), msg.get_path(),
                              "org.freedesktop.DBus.Properties", "Get");
    getSensorUnit.append("xyz.openbmc_project.Sensor.Value", "Unit");
    std::variant<std::string> sensorUnit;
    try {
      sdbusplus::message_t getSensorUnitResp = conn->call(getSensorUnit);
      getSensorUnitResp.read(sensorUnit);
    } catch (const sdbusplus::exception_t &) {
      std::cerr << "Error getting sensor unit from " << msg.get_path() << "\n";
      unit = "Unknown Unit";
    }
    if (unit != "Unknown Unit") {
      unit = std::get<std::string>(sensorUnit);
      std::string unitPrefix("xyz.openbmc_project.Sensor.Value.Unit.");
      if (std::string::size_type pos = unit.find(unitPrefix);
          pos != std::string::npos) {
        unit.erase(pos, unitPrefix.length());
      } else {
        std::cerr << "Error getting sensor unit from " << unit << "\n";
        unit = "Unknown Unit";
      }
    }

    std::string redfishMessage = "";
    if (redfishMessageID != "SensorEvent." + dmtfMessageRegistryVersion +
                                ".SensorReadingNormalRange") {
      // redfishMessage format:
      // <sensorName>,<sensorReading>,<sensorUnit>,<sensorThreshold>
      redfishMessage = std::format(
          "{},{},{},{}", std::string(sensorName.data()),
          std::to_string(assertValue), unit, std::to_string(thresholdVal));
    } else {
      // redfishMessage format:
      // <sensorName>,<sensorReading>,<sensorUnit>
      redfishMessage = std::format("{},{},{}", std::string(sensorName.data()),
                                   std::to_string(assertValue), unit);
    }

#else
    if (eventType != eventNone) {
      sdbusplus::message_t AddToLog = conn->new_method_call(
          "xyz.openbmc_project.Logging", "/xyz/openbmc_project/logging",
          "xyz.openbmc_project.Logging.Create", "Create");
      AddToLog.append(journalMsg, LogLevel,
                      std::map<std::string, std::string>(
                          {{"SENSOR_PATH", std::string(msg.get_path())},
                           {"EVENT", threshold},
                           {"DIRECTION", direction},
                           {"THRESHOLD", std::to_string(thresholdVal)},
                           {"READING", std::to_string(assertValue)}}));
      conn->call(AddToLog);
    }
    std::string redfishMessage = sensorName.data();
    redfishMessage = redfishMessage + "," + std::to_string(assertValue) + "," +
                     std::to_string(thresholdVal);
#endif

    selAddSystemRecord(redfishMessageID, redfishMessage,
                       std::string(msg.get_path()), eventData, assert,
                       selBMCGenID);
#else
    selAddSystemRecord(conn, journalMsg, std::string(msg.get_path()), eventData,
                       assert, selBMCGenID, "REDFISH_MESSAGE_ID=%s",
                       redfishMessageID.c_str(),
                       "REDFISH_MESSAGE_ARGS=%.*s,%f,%f", sensorName.length(),
                       sensorName.data(), assertValue, thresholdVal);
#endif
  };
  sdbusplus::bus::match_t thresholdAssertMatcher(
      static_cast<sdbusplus::bus_t &>(*conn),
      "type='signal', member='ThresholdAsserted'",
      std::move(thresholdAssertMatcherCallback));
  return thresholdAssertMatcher;
}
